package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoTitleReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun titleActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(title="Old title")},soundtrack=p.soundtrack)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"clipTitleEditor",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,text:String="New title"):Boolean {val p=get(a,"project")as VideoEditProject;return call(a,"commitClipTitleReview",d,r,p,0,p.segments[0],text)as Boolean}
 @Test fun titleApplyKeepsUnicodeLinesOtherSettingsMusicProvenanceAndOneUndo(){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val d=editor(a);val r=capture(a);assertTrue(commit(a,d,r,"  New\nScene ✨  "));assertEquals(old[0].copy(title="New\nScene ✨"),p.segments[0]);assertSame(music,p.soundtrack);assertEquals(old[0].captionSourceUri,p.segments[0].captionSourceUri);assertNull(get(a,"clipTitleEditor"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals("New\nScene ✨",p.segments[0].title)}
 @Test fun blankRemovesTitleWhileNoOpDoesNotCreateHistory(){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val d=editor(a);val r=capture(a);assertFalse(commit(a,d,r," Old title "));assertFalse(p.canUndo);assertNull(get(a,"clipTitleEditor"));val remove=editor(a);val current=capture(a);assertTrue(commit(a,remove,current," \n "));assertEquals("",p.segments[0].title);assertTrue(p.undo());assertEquals("Old title",p.segments[0].title);assertFalse(p.canUndo)}
 @Test fun invalidTitleKeepsOwnerEditableForCorrectedRetry(){for(bad in listOf("x".repeat(121),"one\ntwo\nthree\nfour","bad\u0000title","\uD800")){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);try{commit(a,d,r,bad);fail("Accepted invalid title")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(d,get(a,"clipTitleEditor"));assertSame(old,p.segments);assertFalse(p.canUndo);assertTrue(commit(a,d,r,"Allowed"));assertEquals("Allowed",p.segments[0].title);assertNull(get(a,"clipTitleEditor"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun removedDismissedOrReplacedEditorCannotApply(){for(flag in listOf("untracked","dismissed","replaced")){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"clipTitleEditor",dialog())};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceRangeSessionRecoveryAnalysisAndMusicReject(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","analysis","busy","music")){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"range"->set(a,"selectedClip",1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"analysis"->set(a,"analyzing",true);"busy"->set(a,"saving",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertNull(get(a,"clipTitleEditor"))}}
 @Test fun oldEditorCannotConsumeNewAndSuccessfulApprovalCannotReviveAfterUndo(){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val old=editor(a);val current=editor(a);val r=capture(a);assertFalse(commit(a,old,r));assertSame(current,get(a,"clipTitleEditor"));assertTrue(commit(a,current,r));assertFalse(commit(a,current,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,current,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun editedTitleSurvivesExistingDraftRecovery(){val a=titleActivity();val p=get(a,"project")as VideoEditProject;val d=editor(a);val r=capture(a);assertTrue(commit(a,d,r,"New\nScene ✨"));val clip=p.segments[0];val draft=VideoDraft(5000,p.segments,0,0,clip.startMs,clip.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertEquals("New\nScene ✨",restored.segments[0].title);assertEquals("content://synthetic/subtitles",restored.segments[0].captionSourceUri)}
 @Test fun pausedAnalysingOrRecoveringTitleEntryReturnsBeforeWidgets(){for(flag in listOf("pause","analysis","recovery")){val a=titleActivity();when(flag){"pause"->set(a,"workspaceActive",false);"analysis"->set(a,"analyzing",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"editTitle");assertNull(get(a,"clipTitleEditor"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
